const norm = v => (v === null || v === undefined) ? "" : String(v);
const cell = key => norm(pm.iterationData.get(key));

// optional cells hold a JSON literal ("2", 2, true, "false", null); blank = key not sent
const literal = column => {
    const raw = cell(column);
    try {
        return JSON.parse(raw);
    } catch (e) {
        throw new Error(`Test data error: ${column} is not a JSON literal: ${raw}`);
    }
};

["emp_firstName", "emp_lastName", "emp_locationId", "emp_joinedDate"].forEach(column => {
    if (cell(column) === "") {
        throw new Error(`Test data error: ${column} is blank in the CSV row`);
    }
});

// employeeId cell: {UNIQUE} = run-specific id, {UNIQUE50} = run-specific id padded to the 50-character maximum,
// blank = not sent
let employeeId = cell("emp_employeeId");
if (employeeId === "{UNIQUE}" || employeeId === "{UNIQUE50}") {
    const unique = `EMP-${Date.now().toString().slice(-6)}`;
    employeeId = employeeId === "{UNIQUE50}" ? unique.padEnd(50, "x") : unique;
}

const body = {
    firstName: cell("emp_firstName"),
    lastName: cell("emp_lastName"),
    locationId: literal("emp_locationId"),
    joinedDate: cell("emp_joinedDate") === "{TODAY}" ? new Date().toISOString().split("T")[0] : cell("emp_joinedDate")
};
if (cell("emp_middleName") !== "") {
    body.middleName = cell("emp_middleName");
}
if (employeeId !== "") {
    body.employeeId = employeeId;
}
[["chkLogin", "emp_chkLogin"], ["autoGenerateEmployeeId", "emp_autoGenerateEmployeeId"]].forEach(([field, column]) => {
    if (cell(column) !== "") {
        body[field] = literal(column);
    }
});
if (cell("emp_photoBase64") !== "") {
    body.photo = { filename: "employee-photo.png", base64: cell("emp_photoBase64") };
}

// side effect: checked by PIM-045 and PIM-046
pm.environment.set("employee_post_expected", JSON.stringify({
    firstName: body.firstName,
    middleName: norm(body.middleName),
    lastName: body.lastName,
    employeeId: norm(body.employeeId),
    locationId: norm(body.locationId),
    joinedDate: body.joinedDate
}));
pm.variables.set("requestBody", JSON.stringify(body));

