// flt_query holds key=value pairs separated by "&". Tokens: {FIRST} = the folder's first name,
// {A.<field>} = a value of fixture A (B, C alike): an employee field (empNumber, employeeId, locationId,
// fullName = first middle last) or a job record field (job_title_id, subunit_id, work_schedule_id, ...)
const value = (letter, field) => {
    const f = fixtures[letter];
    if (field === "fullName") {
        return [f.firstName, f.middleName, f.lastName].filter(part => part !== "").join(" ");
    }
    if (f[field] !== undefined) {
        return norm(f[field]);
    }
    if (f.job && f.job[field] !== undefined) {
        return norm(f.job[field]);
    }
    throw new Error(`Test data error: fixture field ${letter}.${field} is unknown`);
};
const resolve = text => text.replace(/\{(FIRST|[ABC]\.[A-Za-z_]+)\}/g, (match, token) =>
    token === "FIRST" ? fixtures.firstName : value(token[0], token.slice(2)));
const query = cell("flt_query");
if (query === "") {
    throw new Error("Test data error: flt_query is blank in the CSV row");
}
query.split("&").forEach(pair => {
    const at = pair.indexOf("=");
    if (at < 1) {
        throw new Error(`Test data error: "${pair}" in flt_query is not key=value`);
    }
    pm.request.url.addQueryParams([{ key: pair.slice(0, at), value: resolve(pair.slice(at + 1)) }]);
});

